255: function buildSky(sunDir) {
256:   const geo = new THREE.SphereGeometry(26000, 32, 20);
257:   const mat = new THREE.ShaderMaterial({
258:     side: THREE.BackSide,
259:     depthWrite: false,
260:     fog: false,
261:     toneMapped: false,
262:     uniforms: {
