264:       uZenith: { value: new THREE.Color('#2d6fae') },
265:       uHorizon: { value: new THREE.Color('#d6e7ef') },
266:       uWarm: { value: new THREE.Color('#ffd9a8') },
267:     },
268:     vertexShader: /* glsl */ `
269:       varying vec3 vDir;
270:       void main() {
271:         vDir = normalize(position);
272:         gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
273:       }
