288:         // below horizon fade to sea haze
289:         col = mix(vec3(0.55, 0.66, 0.72), col, smoothstep(-0.12, 0.02, d.y));
290:         // subtle dithering to avoid banding
291:         float dither = fract(sin(dot(d.xz * 900.0, vec2(12.9898, 78.233))) * 43758.5453) * 0.012;
292:         gl_FragColor = vec4(col + dither, 1.0);
293:       }
294:     `,
295:   });
296:   const mesh = new THREE.Mesh(geo, mat);
297:   mesh.frustumCulled = false;
298:   mesh.renderOrder = -100;
299:   return mesh;
300: }
