302: function buildOcean(heightTex) {
303:   const geo = new THREE.PlaneGeometry(60000, 60000, 1, 1);
304:   geo.rotateX(-Math.PI / 2);
305:   const mat = new THREE.ShaderMaterial({
306:     fog: false,
307:     toneMapped: true,
308:     uniforms: {
309:       uTime: { value: 0 },
310:       uHeight: { value: heightTex },
311:       uWorldSize: { value: WORLD_SIZE },
312:       uSunDir: { value: new THREE.Vector3(-0.42, 0.52, -0.74).normalize() },
313:       uSunColor: { value: new THREE.Color('#ffe3b0') },
314:       uDeep: { value: new THREE.Color('#0f3d63') },
315:       uMid: { value: new THREE.Color('#1a6382') },
316:       uShallow: { value: new THREE.Color('#39a6a6') },
317:       uSky: { value: new THREE.Color('#a8cde4') },
318:       uFogColor: { value: new THREE.Color('#c2d9e6') },
319:       uFogDensity: { value: 0.00007 },
320:     },
321:     vertexShader: /* glsl */ `
322:       varying vec3 vWorld;
323:       void main() {
324:         vec4 wp = modelMatrix * vec4(position, 1.0);
325:         vWorld = wp.xyz;
326:         gl_Position = projectionMatrix * viewMatrix * wp;
327:       }
328:     `,
329:     fragmentShader: /* glsl */ `
330:       uniform float uTime, uWorldSize, uFogDensity;
331:       uniform sampler2D uHeight;
332:       uniform vec3 uSunDir, uSunColor, uDeep, uMid, uShallow, uSky, uFogColor;
333:       varying vec3 vWorld;
334: 
335:       void main() {
336:         vec2 uv = clamp(vWorld.xz / uWorldSize + 0.5, 0.001, 0.999);
337:         float h = mix(-300.0, 1900.0, texture2D(uHeight, uv).r);
338:         float depth = max(0.0, -h);
339: 
340:         vec3 viewDir = normalize(cameraPosition - vWorld);
341:         vec2 p = vWorld.xz;
342: 
343:         // layered directional waves
344:         float w1 = sin(p.x * 0.031 + uTime * 0.9) * 0.5 + 0.5;
345:         float w2 = sin(p.y * 0.047 - uTime * 0.7 + p.x * 0.012) * 0.5 + 0.5;
346:         float w3 = sin((p.x + p.y) * 0.021 + uTime * 0.4) * 0.5 + 0.5;
347:         vec2 grad = vec2(
348:           cos(p.x * 0.031 + uTime * 0.9) * 0.031 * 3.0 + cos((p.x + p.y) * 0.021 + uTime * 0.4) * 0.021 * 1.6,
349:           cos(p.y * 0.047 - uTime * 0.7 + p.x * 0.012) * 0.047 * 3.0 + cos((p.x + p.y) * 0.021 + uTime * 0.4) * 0.021 * 1.6
350:         );
351:         float detail = mix(1.0, 0.35, smoothstep(900.0, 9000.0, length(cameraPosition - vWorld)));
352:         vec3 n = normalize(vec3(grad.x * (0.8 + w1) * detail, 1.0, grad.y * (0.8 + w2) * detail));
353: 
354:         float shallow = smoothstep(120.0, 2.0, depth);
355:         vec3 col = mix(uDeep, uMid, smoothstep(420.0, 40.0, depth));
356:         col = mix(col, uShallow, shallow * 0.85);
357: 
358:         // shoreline foam
359:         float foamBand = smoothstep(9.0, 0.2, depth);
360:         float foamWave = 0.55 + 0.45 * sin(uTime * 1.6 + p.x * 0.06 + p.y * 0.045);
361:         col = mix(col, vec3(0.93, 0.98, 1.0), foamBand * foamWave * 0.75);
362: 
363:         float fres = pow(1.0 - clamp(dot(n, viewDir), 0.0, 1.0), 3.0);
364:         col = mix(col, uSky, fres * 0.55);
365: 
366:         vec3 hv = normalize(uSunDir + viewDir);
367:         float spec = pow(max(dot(n, hv), 0.0), 260.0);
368:         col += uSunColor * spec * 2.2;
369: 
370:         float d = length(cameraPosition - vWorld);
371:         float fog = 1.0 - exp(-pow(uFogDensity * d, 2.0));
372:         col = mix(col, uFogColor, fog);
373: 
374:         gl_FragColor = vec4(col, 1.0);
375:       }
376:     `,
377:   });
378:   const mesh = new THREE.Mesh(geo, mat);
379:   mesh.position.y = 0.0;
380:   mesh.renderOrder = 1;
381:   return mesh;
382: }
