388: function buildClouds() {
389:   const group = new THREE.Group();
390:   const rand = rng(4211);
391:   const geo = new THREE.IcosahedronGeometry(1, 1);
392:   const mat = new THREE.MeshStandardMaterial({
393:     color: '#ffffff',
394:     roughness: 1,
395:     metalness: 0,
396:     flatShading: true,
397:     fog: true,
398:     emissive: new THREE.Color('#9fb7cc'),
399:     emissiveIntensity: 0.15,
400:   });
401: 
402:   const puffs = [];
403:   const clusters = 170;
404:   for (let i = 0; i < clusters; i++) {
405:     const a = rand() * Math.PI * 2;
406:     const r = Math.pow(rand(), 0.65) * 7600;
407:     const cx = Math.cos(a) * r;
408:     const cz = Math.sin(a) * r;
409:     const baseY = 620 + rand() * 1500;
410:     const n = 4 + Math.floor(rand() * 5);
411:     const size = 55 + rand() * 120;
412:     for (let j = 0; j < n; j++) {
413:       puffs.push({
414:         x: cx + (rand() - 0.5) * size * 3.2,
415:         y: baseY + (rand() - 0.5) * size * 0.7,
416:         z: cz + (rand() - 0.5) * size * 3.2,
417:         sx: size * (0.7 + rand() * 0.9),
418:         sy: size * (0.24 + rand() * 0.2),
419:         sz: size * (0.7 + rand() * 0.9),
420:         ry: rand() * Math.PI,
421:       });
422:     }
423:   }
424: 
425:   const inst = new THREE.InstancedMesh(geo, mat, puffs.length);
426:   const m = new THREE.Matrix4();
427:   const q = new THREE.Quaternion();
428:   const s = new THREE.Vector3();
429:   const pos = new THREE.Vector3();
430:   for (let i = 0; i < puffs.length; i++) {
431:     const p = puffs[i];
432:     pos.set(p.x, p.y, p.z);
433:     s.set(p.sx, p.sy, p.sz);
434:     q.setFromEuler(new THREE.Euler(0, p.ry, 0));
435:     m.compose(pos, q, s);
436:     inst.setMatrixAt(i, m);
437:   }
438:   inst.instanceMatrix.needsUpdate = true;
439:   inst.frustumCulled = false;
440:   group.add(inst);
441:   return group;
442: }
