20:   const a = hash2(ix, iy, seed);
21:   const b = hash2(ix + 1, iy, seed);
22:   const c = hash2(ix, iy + 1, seed);
23:   const d = hash2(ix + 1, iy + 1, seed);
24: 
25:   return lerp(lerp(a, b, fx), lerp(c, d, fx), fy) * 2 - 1;
