28: // Fractal brownian motion in [-1, 1]
29: export function fbm2(x, y, octaves = 4, seed = 7, lacunarity = 2.03, gain = 0.5) {
30:   let amp = 1;
31:   let freq = 1;
32:   let sum = 0;
33:   let norm = 0;
34:   let rot = 0;
35:   for (let i = 0; i < octaves; i++) {
36:     // Rotate each octave a little so the value-noise grid doesn't line up.
37:     const rx = x * Math.cos(rot) - y * Math.sin(rot);
38:     const ry = x * Math.sin(rot) + y * Math.cos(rot);
39:     sum += valueNoise2(rx * freq, ry * freq, seed + i * 131) * amp;
40:     norm += amp;
41:     amp *= gain;
42:     freq *= lacunarity;
43:     rot += 0.72;
44:   }
45:   return sum / norm;
46: }
