34: /** World height in metres at x/z. Sea floor is negative. */
35: export function heightAt(x, z) {
36:   let h = -150;
37: 
38:   for (let i = 0; i < ISLANDS.length; i++) {
39:     const is = ISLANDS[i];
40:     const dx = x - is.x;
41:     const dz = z - is.z;
42:     const d = Math.sqrt(dx * dx + dz * dz) / is.r;
43:     if (d < 1.6) {
44:       const shape = smoothstep(1.42, 0.12, d);
45:       const wob = 1 + fbm2(x * 0.0011, z * 0.0011, 3, 91 + i * 17) * 0.38;
46:       h += is.h * shape * Math.max(0.1, wob);
47:     }
48:   }
49: 
50:   const landness = smoothstep(-40, 45, h);
51:   h += fbm2(x * 0.0011, z * 0.0011, 5, 13) * 28 * landness;
52: 
53:   // Mountain ridges above a certain base altitude.
54:   const mAmt = smoothstep(130, 720, h);
55:   if (mAmt > 0.002) {
56:     const r = ridged2(x * 0.00055, z * 0.00055, 5, 77);
57:     h += Math.pow(r, 2.2) * 620 * mAmt;
58:   }
59: 
60:   h += fbm2(x * 0.0062, z * 0.0062, 3, 41) * 5.2 * landness;
61: 
62:   // Flatten a generous plateau for the airfield.
63:   const ad = Math.hypot(x - AIRFIELD.x, z - AIRFIELD.z);
64:   if (ad < 2400) {
65:     const w = smoothstep(2400, 620, ad);
66:     h = lerp(h, AIRFIELD.y, w);
67:   }
68:   return h;
69: }
